export const editWindow = async (payload) => {
  const rs = ruleset(payload.jurisdiction);
  if (!rs) return unknownJurisdiction(payload.jurisdiction);

  const generated = new Date(payload.generatedAt);
  if (Number.isNaN(generated.getTime())) {
    return { verdict: 'BAD_TIMESTAMP', message: 'generatedAt could not be parsed. Pass ISO 8601 with an offset, e.g. 2026-11-12T09:30:00+05:00.' };
  }

  const hours = rs.channelRules.editWindowHours;
  const deadline = new Date(generated.getTime() + hours * 3600 * 1000);
  const now = new Date();
  const msLeft = deadline - now;
  const open = msLeft > 0;

  return {
    verdict: open ? 'WINDOW_OPEN' : 'WINDOW_CLOSED',
    jurisdiction: rs.code,
    generatedAt: generated.toISOString(),
    deadline: deadline.toISOString(),
    hoursRemaining: open ? Math.floor(msLeft / 3600000) : 0,
    minutesRemaining: open ? Math.floor((msLeft % 3600000) / 60000) : 0,
    canDoInSoftware: open,
    rule: hours + ' hours from generation to cancel, delete or edit through the authority system.',
    source: rs.channelRules.editWindowSource,
    ifClosed: rs.channelRules.afterWindow,
  };
};

export const checkChannel = async (payload) => {
  const rs = ruleset(payload.jurisdiction);
  if (!rs) return unknownJurisdiction(payload.jurisdiction);

  const seller = normaliseId(payload.sellerNTNCNIC);
  const buyer = normaliseId(payload.buyerNTNCNIC);
  const registered = /registered/i.test(String(payload.buyerRegistrationType || '')) &&
    !/unregistered|not applicable/i.test(String(payload.buyerRegistrationType || ''));

  if (seller && buyer && seller === buyer) {
    return {
      verdict: 'REJECTED',
      channel: 'none',
      reason: rs.channelRules.posVsDigital[2].why,
      source: 'DI API V1.12 / PRAL validation code 0058',
      nextAction: 'Delete the payload; an invoice cannot be issued to the same person who issues it.',
    };
  }

  const chosen = registered ? rs.channelRules.posVsDigital[0] : rs.channelRules.posVsDigital[1];
  return {
    verdict: 'CHANNEL_ASSIGNED',
    jurisdiction: rs.code,
    channel: chosen.channel,
    reason: chosen.why,
    invoiceType: payload.invoiceType || 'Sale Invoice',
    nextAction: chosen.channel === 'POS'
      ? 'Obtain the invoice number from the fiscal component; the application must not re-post it.'
      : 'Send the buyer identifier and registration type in the payload; they are mandatory for this channel.',
  };
};

